}

/// <summary>一套主题的 radii（7 个）。</summary>
public sealed class ThemeRadii
{
    /// <summary>none = 0（设备无关像素）：`0`</summary>
    public required float None { get; init; }

    /// <summary>xs = 0.15em（em 系数）：`0.15em`：控件内的小元素</summary>
    public required float Xs { get; init; }

    /// <summary>sm = 0.25em（em 系数）：`0.25em`：标签、复选框</summary>
    public required float Sm { get; init; }

    /// <summary>md = 0.4em（em 系数）：`0.4em`：按钮、输入框</summary>
    public required float Md { get; init; }

    /// <summary>lg = 0.7em（em 系数）：`0.7em`：卡片、浮层</summary>
    public required float Lg { get; init; }

    /// <summary>xl = 1em（em 系数）：`1em`：对话框</summary>
    public required float Xl { get; init; }

    /// <summary>full = 9999px（设备无关像素）：全圆：胶囊按钮、头像、开关</summary>
    public required float Full { get; init; }
}

/// <summary>一套内置主题随主题变的 token（colors、shadows、fonts、radii）；其余 token 不随主题变，见 Tokens。</summary>
public sealed class ThemeTokens
{
    /// <summary>名字，同 vue-tsx-pro 的 builtinThemes（light、high-contrast……）。</summary>
    public required string Name { get; init; }

    /// <summary>中文名。</summary>
    public required string Label { get; init; }

    /// <summary>是不是暗色主题。</summary>
    public required bool IsDark { get; init; }

    /// <summary>colors</summary>
    public required ThemeColors Colors { get; init; }

    /// <summary>shadows</summary>
    public required ThemeShadows Shadows { get; init; }

    /// <summary>fonts</summary>
    public required ThemeFonts Fonts { get; init; }

    /// <summary>radii</summary>
    public required ThemeRadii Radii { get; init; }
}

